    $out = [];
    foreach ($rows as $row) {
        $out[] = [
            'group' => $row[0],
            'key' => $row[1],
            'type' => $row[2],
            'fa' => $row[3],
            'en' => $row[4],
        ];
    }
    return $out;
}

function cms_registry_groups(): array
{
    $groups = [];
    foreach (cms_registry() as $row) {
        $groups[$row['group']] = true;
    }
    return array_keys($groups);
}

